import AdHero from '../components/AdHero';
import AdStrip from '../components/AdStrip';

const Women = () => {
    return (
        <div className="min-h-screen bg-white font-display">
            <AdHero page="women" />
            <AdStrip page="women" />

            <div className="max-w-[1440px] mx-auto py-16 px-6 lg:px-12 text-center">
                <h2 className="text-3xl font-extrabold text-[#10221c] uppercase tracking-tighter">Women's Collection</h2>
                <p className="text-gray-500 mt-4 max-w-2xl mx-auto">Explore elegant silhouettes and premium sportswear designed for the modern woman.</p>
            </div>
        </div>
    );
};

export default Women;
